// Screen-sized research sheets. Detail is revealed deliberately, never discarded.
const $=id=>document.getElementById(id);
const pages=new Map();
let inventoryNode=null;
function node(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n}
export function showLongText(title,text){$('detailTitle').textContent=title;$('detailText').textContent=text||'No text available.';$('detailDialog').showModal()}
function tabs(id,items){const root=$(id),bar=node('div','compact-tabs');bar.setAttribute('role','group');bar.setAttribute('aria-label','Views in this sheet');let selected=0;items=items.filter(x=>x[1]);items.forEach(([label,panel],i)=>{panel.classList.add('compact-subview');panel.dataset.compactPanel=id;const b=node('button','',label);b.type='button';b.setAttribute('aria-pressed',String(!i));b.onclick=()=>{selected=i;apply();refreshCompact()};bar.append(b)});function apply(){items.forEach(([label,panel],i)=>{panel.hidden=i!==selected;bar.children[i].setAttribute('aria-pressed',String(i===selected))})}const anchor=root.querySelector('.section-head')||root.firstElementChild;anchor.after(bar);items.forEach(([label,panel])=>root.append(panel));apply();return bar}
function group(...els){const g=node('div','compact-group');els.filter(Boolean).forEach(e=>g.append(e));return g}
function fullButton(target,title,label='Read full text ↗'){if(!target||target.dataset.fullButton)return;target.dataset.fullButton='yes';const b=node('button','detail-trigger',label);b.type='button';b.onclick=()=>{const copy=target.cloneNode(true);copy.querySelectorAll('button,.page-controls').forEach(n=>n.remove());showLongText(title,copy.textContent)};if(target.matches('article,aside,.panel'))target.append(b);else target.after(b)}
function pager(container,selector,key,max=8){if(!container||!container.getClientRects().length)return;let children=[...container.querySelectorAll(selector)];if(!children.length){const host=container.tagName==='TBODY'?container.closest('table').parentElement:container.parentElement;const old=host.querySelector(`:scope > [data-pager="${key}"]`);if(old)old.hidden=true;return;}let p=pages.get(key)||0;children.forEach(c=>c.hidden=false);const mobile=innerWidth<600,short=innerHeight<760;let size=Math.min(max,mobile?(short?3:4):(short?5:8));const measured=Math.max(...children.map(c=>c.getBoundingClientRect().height));if(measured>0){const top=container.getBoundingClientRect().top,budget=innerHeight-top-(mobile?94:85);size=Math.max(1,Math.min(size,Math.floor(budget/(measured+7))))}const total=Math.ceil(children.length/size);p=Math.min(p,Math.max(0,total-1));pages.set(key,p);children.forEach((c,i)=>c.hidden=i<p*size||i>=(p+1)*size);const host=container.tagName==='TBODY'?container.closest('table').parentElement:container.parentElement;let controls=host.querySelector(`:scope > [data-pager="${key}"]`);if(!controls){controls=node('div','page-controls');controls.dataset.pager=key;(container.tagName==='TBODY'?container.closest('table'):container).after(controls)}controls.hidden=total<=1;controls.replaceChildren();const prev=node('button','','← Previous'),label=node('span','',`${p*size+1}–${Math.min((p+1)*size,children.length)} of ${children.length}`),next=node('button','','Next →');prev.disabled=!p;next.disabled=p>=total-1;prev.onclick=()=>{pages.set(key,p-1);refreshCompact()};next.onclick=()=>{pages.set(key,p+1);refreshCompact()};controls.append(prev,label,next);}
let ready=false;
function setup(){if(ready)return;ready=true;document.body.classList.add('compact-workspace');
 const detail=node('dialog','detail-dialog');detail.id='detailDialog';detail.innerHTML='<button class="dialog-close" id="detailClose" aria-label="Close detail">×</button><h2 id="detailTitle"></h2><div id="detailText" class="detail-text"></div>';document.body.append(detail);$('detailClose').onclick=()=>detail.close();
 const fd=node('dialog','filter-dialog');fd.id='filterDialog';fd.innerHTML='<button class="dialog-close" id="filterClose" aria-label="Close filters">×</button><h2>Filter the active release</h2><p>These choices apply across research sheets.</p>';fd.append(document.querySelector('.filters'),$('verifiedControls'),$('activeFilters'));const done=node('button','primary','Apply & close');done.onclick=()=>fd.close();fd.append(done);document.body.append(fd);$('filterClose').onclick=()=>fd.close();
 const dock=document.querySelector('.control-dock'),row=document.querySelector('.cohort-line');const filter=node('button','filter-open','Filters');filter.id='filterOpen';filter.onclick=()=>fd.showModal();const summary=node('span','filter-summary');summary.id='compactFilterSummary';dock.prepend(group(filter,summary));dock.firstElementChild.classList.add('compact-filter-row');
 // Each chapter's introductory explanation remains available without occupying chart space.
 document.querySelectorAll('[data-sheet] > .section-head').forEach(h=>{const p=h.querySelector('p');if(p){const b=node('button','sheet-help','ⓘ');b.setAttribute('aria-label','About this view');b.onclick=()=>showLongText(h.querySelector('h2')?.textContent||'About this view',p.textContent);h.append(b)}});
 const ds=$('decisions'),chart=ds.querySelector('.chart-grid');tabs('decisions',[['Outcomes',chart.children[0]],['Decision time',chart.children[1]]]);chart.remove();
 const reasonPanels=[...$('reasonsContent').children].filter(e=>e.classList.contains('panel'));const rt=tabs('reasons',[['Categories',reasonPanels[0]],['Evidence',reasonPanels[1]],['Boroughs',reasonPanels[2]]]);$('reasonsContent').append(rt,...reasonPanels); // Preserve release-level empty states.
 const sizePanels=[...$('sizesContent').children].filter(e=>e.classList.contains('panel')||e.classList.contains('provenance-note'));const st=tabs('sizes',[['Area bands',sizePanels[0]],['Extractor flag',sizePanels[1]],['Interpretation',sizePanels[2]]]);$('sizesContent').append(st,...sizePanels);
 const retry=$('retriesContent'),coverage=$('retryCoverage'),outcome=retry.querySelector(':scope > .panel'),toolbar=retry.querySelector('.pair-toolbar'),comparison=group(toolbar,$('pairMeta'),$('pairWarning'),retry.querySelector('.pair-grid'),$('pairTags')),text=retry.querySelector('details'),explain=retry.querySelector('.filter-explainer'),note=retry.querySelector(':scope > .micro');text.open=true;const ov=group(explain,coverage,outcome),tx=group(text,note);const rtab=tabs('retries',[['Overview',ov],['Compare pair',comparison],['Refusal text',tx]]);retry.append(rtab,ov,comparison,tx);fullButton($('pairReasonText'),'Supplied refusal text');
 const research=[...$('evidence').querySelectorAll('.research-card')];tabs('evidence',[['Space',research[0]],['Requirements',research[1]],['Revisions',research[2]],['Status',research[3]]]);$('evidence').querySelector('.evidence-layout').remove();
 const spot=$('spotlight'),grid=spot.querySelector('.case-grid'),main=grid.querySelector('.case-main'),verify=grid.querySelector('.case-evidence'),reason=$('caseReasonList'),records=spot.querySelector('.records');records.open=true;const noReasons=node('p','micro','Reason excerpts appear here when the selected record has a supplied classification. No reason is inferred for missing text.');const reasons=group(noReasons,reason);tabs('spotlight',[['Proposal',main],['Verification',verify],['Reasons',reasons],['Register',records]]);grid.remove();fullButton($('caseDescription'),'Original proposal');fullButton($('caseDecision'),'Original decision wording');
 const sources=$('sources'),coveragePanel=sources.querySelector('.data-table-panel'),details=[...sources.querySelectorAll(':scope > .detail-panel')],files=node('div');files.id='compactSourceFiles';const other=group(details[1],sources.querySelector(':scope > .provenance-note'));tabs('sources',[['Release',$('releaseInventory')],['Coverage',coveragePanel],['Files',files],['Next steps',details[0]],['Map & model',other]]);
 // Long source paragraphs have explicit on-demand full descriptions.
 document.querySelectorAll('#sources .section-head p,#overview .sublead').forEach(e=>e.classList.add('compact-optional'));
 fullButton(document.querySelector('#spotlight .case-evidence'),'Verification details','Read verification notes ↗');
 document.addEventListener('click',e=>{if(e.target.closest('[data-row],[data-evidence-id]')){const proposal=[...$('spotlight').querySelectorAll('.compact-tabs button')].find(b=>b.textContent==='Proposal');proposal?.click();}if(e.target.closest('[data-sheet-target],.compact-tabs button,#rankView,#mapView,[data-cohort],[data-reason]'))requestAnimationFrame(refreshCompact)});
 window.addEventListener('resize',()=>requestAnimationFrame(refreshCompact));
}
export function refreshCompact(){if(!ready)return;
 const filters=['borough','year','outcome','category'].map(id=>$(id)?.value).filter(Boolean);const extra=$('activeFilters')?.textContent.replaceAll('×','').trim();$('compactFilterSummary').textContent=filters.length?filters.join(' · '):'All authorities · all years · all outcomes';$('compactFilterSummary').title=extra||'All available records in the selected release';$('filterOpen').textContent=filters.length?`Filters (${filters.length})`:'Filters';
 // Source inventory is regenerated on release changes; keep its manifest in the Files view.
 const inv=$('releaseInventory'),manifest=inv.querySelector('.detail-panel');if(inventoryNode!==inv.firstElementChild){inventoryNode=inv.firstElementChild;if(manifest){$('compactSourceFiles').replaceChildren(manifest);fullButton(manifest,'File manifest','Read complete manifest ↗')}else $('compactSourceFiles').replaceChildren(node('p','provenance-note','The original Foundations CSV hash and snapshot details are listed under Release. The supplied conversion-file manifest belongs to the other data release.'));}
 inv.querySelectorAll('.source-cards > article,.panel:not(.detail-panel)').forEach(card=>fullButton(card,'Release provenance','Read source details ↗'));
 const active=document.querySelector('[data-sheet]:not([hidden])');if(!active)return;const modelView=active.id==='concept';document.querySelector('.cohort-line').hidden=modelView;$('filterOpen').disabled=modelView;if(modelView){$('compactFilterSummary').textContent='Independent supplied model · planning filters do not apply';$('filterOpen').textContent='Model view';}
 if(active.id==='london'){if(!$('rankPanel').hidden)pager($('boroughRank'),'.rank-row','boroughs',10);else{$('map').style.height='';const over=Math.max($('mapPanel').getBoundingClientRect().bottom-($('sheetStage').getBoundingClientRect().bottom-12),$('sheetStage').scrollHeight-$('sheetStage').clientHeight);if(over>0)$('map').style.height=Math.max(90,$('map').getBoundingClientRect().height-over)+'px';}}
 if(active.id==='reasons'){
  pager($('reasonChart'),'.analysis-bar','reason-bars',8);
  pager($('reasonEvidenceRows'),'.excerpt','reason-evidence',2);
  compactHeatmap();
 }
 if(active.id==='spotlight'){
  pager($('caseReasonList'),'.case-reason','case-reasons',2);
  pager($('caseTable'),'tr','records',6);
 }
 if(active.id==='sources'){
  pager($('missingnessTable'),'tr','missingness',6);
  const manifestBody=$('compactSourceFiles').querySelector('tbody');if(manifestBody)pager(manifestBody,'tr','manifest',4);
  const backlog=active.querySelector('.fill-panel tbody')||[...active.querySelectorAll('tbody')].find(e=>e.textContent.includes('Review descriptions'));if(backlog)pager(backlog,'tr','backlog',3);
 }
 document.querySelectorAll('#refusedPairCard,#nextPairCard').forEach(card=>fullButton(card,'Full matched application','Read full application ↗'));
 // A measured height class adjusts chart density without reducing type to illegible sizes.
 document.body.classList.toggle('short-screen',innerHeight<760);document.body.classList.remove('pair-tight');if(active.id==='retries'&&$('pairSelect').getClientRects().length&&$('sheetStage').scrollHeight>$('sheetStage').clientHeight+1)document.body.classList.add('pair-tight');
}
function compactHeatmap(){const wrap=$('reasonHeatmap'),table=wrap.querySelector('table');if(!table)return;if(!table.dataset.compact){table.dataset.compact='yes';const headers=[...table.querySelectorAll('thead th')].slice(1);let select=wrap.parentElement.querySelector('.heatmap-category');if(!select){select=node('select','heatmap-category');select.setAttribute('aria-label','Heatmap reason');wrap.before(select)}select.innerHTML=headers.map((h,i)=>`<option value="${i+1}">${h.textContent}</option>`).join('');const apply=()=>{const col=Number(select.value);[...table.rows].forEach(row=>[...row.cells].forEach((cell,i)=>cell.hidden=i!==0&&i!==col));refreshCompact()};select.onchange=apply;const col=Number(select.value);[...table.rows].forEach(row=>[...row.cells].forEach((cell,i)=>cell.hidden=i!==0&&i!==col));}pager(table.tBodies[0],'tr','heatmap',6);}
setup();
